      belakang += '<line class="zn-ref" x1="' + PADL + '" x2="' + f(kanan) + '" y1="' + f(yr) + '" y2="' + f(yr) + '">'
        + '<title>Next Structural Support ' + rb(Z.refBawah) + '</title></line>';
      depan += teksBerlatar('zn-t zn-t-bawah', PADL + 5, yr - 3, 'Next Structural Support', 'start');
