    if (!isFinite(y1) || !isFinite(y2)) continue;
    const yLbl = y2 + (sk.kelas === 'turun' ? 10 : -4);
    depan += '<line class="an-sk an-sk-' + sk.kelas + ' an-sk-' + String(sk.tahap).toLowerCase() + '" x1="' + f(xAkhir) + '" y1="' + f(y1)
