    const perJenis = new Map();
    for (const p of (A.peristiwa || []).filter(p => p.i >= i0 && p.i < END).sort((a, b) => a.i - b.i)) perJenis.set(p.jenis, p);
    // PRIORITAS lebih dulu, lalu yang terbaru
    const urut = [...perJenis.values()].sort((a, b) => (a.prioritas || 4) - (b.prioritas || 4) || b.i - a.i).slice(0, maks);
    const rak = { atas: [], bawah: [] };
