      const sisi = p.sisi === 'atas' ? 'atas' : 'bawah';
      let baris = -1;
      for (let b = 0; b < 3; b++) {
        if (!rak[sisi].some(r => r.baris === b && xc - lebar < r.kanan && r.kiri < xc + lebar)) { baris = b; break; }
      }
